// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * End-to-end SPARQL tests for the {@code winf:} window functions on a {@link MemoryStore}.
 */
public class WindowFunctionSparqlTest {

	private static final String PREFIXES = "PREFIX winf: <http://rdf4j.org/function/window#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		// sales: a=10, b=30, c=30, d=40 ; eng: e=50, f=70
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:a ex:dept ex:sales ; ex:salary 10 ; ex:name \"a\" .\n"
				+ "ex:b ex:dept ex:sales ; ex:salary 30 ; ex:name \"b\" .\n"
				+ "ex:c ex:dept ex:sales ; ex:salary 30 ; ex:name \"c\" .\n"
				+ "ex:d ex:dept ex:sales ; ex:salary 40 ; ex:name \"d\" .\n"
				+ "ex:e ex:dept ex:eng ; ex:salary 50 ; ex:name \"e\" .\n"
				+ "ex:f ex:dept ex:eng ; ex:salary 70 ; ex:name \"f\" .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	private static List<BindingSet> query(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	private static List<String> column(List<BindingSet> rows, String var) {
		List<String> values = new ArrayList<>();
		for (BindingSet row : rows) {
			values.add(row.hasBinding(var) ? row.getValue(var).stringValue() : null);
		}
		return values;
	}

	private static final String BASE = "WHERE { ?p ex:dept ?dept ; ex:salary ?salary ; ex:name ?name } ORDER BY ?name";

	@Test
	void rankingFunctions() {
		List<BindingSet> rows = query(
				"SELECT ?name (winf:rowNumber(winf:partitionBy(?dept), winf:orderBy(?salary, ?name)) AS ?rn)"
						+ " (winf:rank(winf:partitionBy(?dept), winf:orderBy(?salary)) AS ?rank)"
						+ " (winf:denseRank(winf:partitionBy(?dept), winf:orderBy(?salary)) AS ?dense)"
						+ " (winf:percentRank(winf:partitionBy(?dept), winf:orderBy(?salary)) AS ?pr)"
						+ " (winf:cumeDist(winf:partitionBy(?dept), winf:orderBy(?salary)) AS ?cd)"
						+ " (winf:ntile(2, winf:partitionBy(?dept), winf:orderBy(?salary, ?name)) AS ?tile) " + BASE);
		assertThat(column(rows, "name")).containsExactly("a", "b", "c", "d", "e", "f");
		assertThat(column(rows, "rn")).containsExactly("1", "2", "3", "4", "1", "2");
		assertThat(column(rows, "rank")).containsExactly("1", "2", "2", "4", "1", "2");
		assertThat(column(rows, "dense")).containsExactly("1", "2", "2", "3", "1", "2");
		assertThat(column(rows, "pr")).containsExactly("0.0", "0.3333333333333333", "0.3333333333333333", "1.0", "0.0",
				"1.0");
		assertThat(column(rows, "cd")).containsExactly("0.25", "0.75", "0.75", "1.0", "0.5", "1.0");
		assertThat(column(rows, "tile")).containsExactly("1", "1", "2", "2", "1", "2");
	}

	@Test
	void navigationFunctions() {
		List<BindingSet> rows = query(
				"SELECT ?name (winf:lag(?name, winf:partitionBy(?dept), winf:orderBy(?name)) AS ?prev)"
						+ " (winf:lead(?name, 1, \"none\", winf:partitionBy(?dept), winf:orderBy(?name)) AS ?next)"
						+ " (winf:lag(?salary, 2, winf:orderBy(?name)) AS ?lag2)"
						+ " (winf:firstValue(?name, winf:partitionBy(?dept), winf:orderBy(?salary, ?name)) AS ?first)"
						+ " (winf:lastValue(?name, winf:partitionBy(?dept), winf:orderBy(?salary, ?name)) AS ?lastDefault)"
						+ " (winf:lastValue(?name, winf:partitionBy(?dept), winf:orderBy(?salary, ?name), winf:rows(\"unbounded\", \"unbounded\")) AS ?last)"
						+ " (winf:nthValue(?name, 2, winf:partitionBy(?dept), winf:orderBy(?salary, ?name), winf:range(\"unbounded\", \"unbounded\")) AS ?second) "
						+ BASE);
		assertThat(column(rows, "prev")).containsExactly(null, "a", "b", "c", null, "e");
		assertThat(column(rows, "next")).containsExactly("b", "c", "d", "none", "f", "none");
		assertThat(column(rows, "lag2")).containsExactly(null, null, "10", "30", "30", "40");
		assertThat(column(rows, "first")).containsExactly("a", "a", "a", "a", "e", "e");
		// default frame ends at the current row (peers included)
		assertThat(column(rows, "lastDefault")).containsExactly("a", "b", "c", "d", "e", "f");
		assertThat(column(rows, "last")).containsExactly("d", "d", "d", "d", "f", "f");
		assertThat(column(rows, "second")).containsExactly("b", "b", "b", "b", "f", "f");
	}

	@Test
	void aggregateWindowFunctions() {
		List<BindingSet> rows = query("SELECT ?name (winf:sum(?salary, winf:partitionBy(?dept)) AS ?total)"
				+ " (winf:sum(?salary, winf:partitionBy(?dept), winf:orderBy(?salary)) AS ?running)"
				+ " (winf:avg(?salary, winf:partitionBy(?dept)) AS ?avg)"
				+ " (winf:count(?salary, winf:partitionBy(?dept), winf:orderBy(?name)) AS ?cnt)"
				+ " (winf:min(?salary, winf:partitionBy(?dept)) AS ?min)"
				+ " (winf:max(?salary, winf:orderBy(?name), winf:rows(-1, 0)) AS ?maxPrev)"
				+ " (winf:sum(?salary, winf:orderBy(?name), winf:rows(-1, 1)) AS ?moving)"
				+ " (winf:avg(?salary, winf:orderBy(?name), winf:rows(0, 1)) AS ?movingAvg) " + BASE);
		assertThat(column(rows, "total")).containsExactly("110", "110", "110", "110", "120", "120");
		// running sum: peers share the frame end (RANGE semantics of the default frame)
		assertThat(column(rows, "running")).containsExactly("10", "70", "70", "110", "50", "120");
		assertThat(column(rows, "avg")).containsExactly("27.5", "27.5", "27.5", "27.5", "60", "60");
		assertThat(column(rows, "cnt")).containsExactly("1", "2", "3", "4", "1", "2");
		assertThat(column(rows, "min")).containsExactly("10", "10", "10", "10", "50", "50");
		assertThat(column(rows, "maxPrev")).containsExactly("10", "30", "30", "40", "50", "70");
		assertThat(column(rows, "moving")).containsExactly("40", "70", "100", "120", "160", "120");
		assertThat(column(rows, "movingAvg")).containsExactly("20", "30", "35", "45", "60", "70");
		Literal total = (Literal) rows.get(0).getValue("total");
		assertThat(total.getDatatype().getLocalName()).isEqualTo("integer");
	}

	@Test
	void windowOverGroupedResultsAndOrderingByWindowResult() {
		List<BindingSet> rows = query("SELECT ?dept (SUM(?salary) AS ?total)"
				+ " (winf:rank(winf:orderBy(winf:desc(SUM(?salary)))) AS ?rank)"
				+ " (winf:sum(SUM(?salary)) AS ?grand)"
				+ " WHERE { ?p ex:dept ?dept ; ex:salary ?salary } GROUP BY ?dept ORDER BY ?rank");
		assertThat(column(rows, "total")).containsExactly("120", "110");
		assertThat(column(rows, "rank")).containsExactly("1", "2");
		assertThat(column(rows, "grand")).containsExactly("230", "230");
	}

	@Test
	void windowResultsUsableInExpressionsDistinctAndSubselect() {
		List<BindingSet> rows = query("SELECT DISTINCT ?dept ?top WHERE { { SELECT ?dept ?name"
				+ " (winf:rowNumber(winf:partitionBy(?dept), winf:orderBy(winf:desc(?salary), ?name)) AS ?rn)"
				+ " WHERE { ?p ex:dept ?dept ; ex:salary ?salary ; ex:name ?name } }"
				+ " FILTER(?rn = 1) BIND(?name AS ?top) } ORDER BY ?dept");
		assertThat(column(rows, "top")).containsExactly("f", "d");
		rows = query("SELECT (winf:rowNumber(winf:orderBy(?name)) * 100 + winf:rank(winf:orderBy(?salary)) AS ?code) "
				+ BASE);
		assertThat(column(rows, "code")).containsExactly("101", "202", "302", "404", "505", "606");
	}

	@Test
	void emptyInputAndNoOrderWholePartitionFrame() {
		List<BindingSet> rows = query("SELECT (winf:rowNumber() AS ?rn) WHERE { ?p ex:nothing ?x }");
		assertThat(rows).isEmpty();
		rows = query("SELECT ?name (winf:count(?salary) AS ?all) (winf:lastValue(?name, winf:orderBy(?name)) AS ?lv) "
				+ BASE);
		assertThat(column(rows, "all")).containsExactly("6", "6", "6", "6", "6", "6");
		assertThat(column(rows, "lv")).containsExactly("a", "b", "c", "d", "e", "f");
	}

	@Test
	void misuseIsReported() {
		// outside SELECT expressions a window function is a syntax error rather than a silently unbound variable
		assertThatThrownBy(
				() -> query("SELECT ?x WHERE { ?p ex:salary ?s BIND(winf:rowNumber() AS ?x) FILTER(?x > 0) }"))
						.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> query("SELECT ?x WHERE { ?p ex:salary ?s FILTER(winf:rowNumber() > 0) }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> query("SELECT (winf:sum(?s, winf:partitionBy(winf:rowNumber())) AS ?t)"
				+ " WHERE { ?p ex:salary ?s }")).isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> query("SELECT (winf:sum(?s, winf:orderBy(?s), winf:rows(\"current\","
				+ " \"unbounded preceding\")) AS ?t) WHERE { ?p ex:salary ?s }"))
						.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> query("SELECT (winf:ntile(0, winf:orderBy(?s)) AS ?t) WHERE { ?p ex:salary ?s }"))
				.isInstanceOf(QueryEvaluationException.class);
		assertThatThrownBy(() -> query(
				"SELECT (winf:sum(?s, winf:orderBy(?s), winf:range(-1, 0)) AS ?t) WHERE { ?p ex:salary ?s }"))
						.isInstanceOf(QueryEvaluationException.class);
	}

	@Test
	void dataDependentIntegerArgumentsLeaveOnlyThatRowUnbound() {
		// a per-row offset that is unbound or not an integer is an evaluation error for that row only
		List<BindingSet> rows = query("SELECT ?x (winf:lag(?x, ?off, winf:orderBy(?x)) AS ?prev)"
				+ " (winf:ntile(?n, winf:orderBy(?x)) AS ?tile)"
				+ " (winf:nthValue(?x, ?n, winf:orderBy(?x), winf:rows(\"unbounded\", \"unbounded\")) AS ?nth)"
				+ " WHERE { VALUES (?x ?off ?n) { (1 1 2) (2 UNDEF UNDEF) (3 \"a\" 1.5) (4 2 2) } } ORDER BY ?x");
		assertThat(column(rows, "x")).containsExactly("1", "2", "3", "4");
		assertThat(column(rows, "prev")).containsExactly(null, null, null, "2");
		assertThat(column(rows, "tile")).containsExactly("1", null, null, "2");
		assertThat(column(rows, "nth")).containsExactly("2", null, null, "2");
		// constant arguments are still validated up front
		assertThatThrownBy(() -> query("SELECT (winf:lag(?x, -1, winf:orderBy(?x)) AS ?p) WHERE { VALUES ?x {1 2} }"))
				.isInstanceOf(QueryEvaluationException.class);
	}
}
